        "Due to rib fracture, the intercostal vessels are damaged, parietal pleura is torn, and blood flows into the pleural space.\nThe loss of negative pressure within the pleural cavity results in collapse of the lung.\nThe carotid vessels would not be affected by the described injury.\nThe pulmonary vessels are found within the parenchyma of the lungs and would not be injured due to an external injury such as that described.\nThe internal thoracic artery is well protected by the sternum and is not the cause of this hemothorax.\n\n\n\n**BRS says:**\n\n**Intercostal nerves** run between the internal and innermost layers of muscles, with the intercostal veins and arteries above (veins, arteries, nerves [VAN]). Are lodged in the costal grooves on the inferior surface of the ribs.\n\n(Chapter 3, Thorax — Thoracic Wall: Nerves and Blood Vessels)",
