      explanation:
        "The murmur at S2 localizes the defect at an atrioventricular valve.\nAn ASD causes a diastolic murmur in the tricuspid valve, whereas a VSD would cause a pansystolic murmur.\nTransposition of the great arteries and aortic stenosis will cause a murmur at S1, and tetralogy of Fallot does not cause a murmur at S1 or S2.\n\n\n\n**BRS says:**\n\n**Atrial septal defect (ASD)** is a congenital defect in the septum between the atria due to failure of the foramen primum or secundum to close normally, resulting in a patent foramen ovale. This defect shunts blood from the left atrium to the right atrium and causes hypertrophy of the right atrium, right ventricle, and pulmonary trunk. Signs include abnormal heart sounds, murmur, and a **wide, fixed, split S2**.\n\n(Chapter 3, Thorax — Clinical Correlates: ASD)",
