      q: "A 4-year-old girl is admitted to the hospital with high fever. Staphylococcus aureus is isolated from her blood cultures and antibiotic therapy is initiated. A loud, harsh murmur is heard on auscultation. A chest radiograph shows prominent pulmonary arteries. Echocardiography shows all the valves to be normal. Which congenital heart disease most likely explains these findings?",
