      q: "A 55-year-old man is brought to the emergency department after his motorcycle collided with an automobile. He is hypotensive, his pulse is irregular, and he shows other signs of substantial blood loss. MRI and CT scan evaluations reveal profuse abdominal bleeding. A decision is made to enter the chest so that the descending thoracic aorta can be clamped to minimize blood loss and to preserve cerebral blood flow. After surgical entrance into the thorax, the fibrous pericardium is elevated with forceps and punctured. A midline, longitudinal incision of the pericardium would best be made to prevent injury to which of the following structures?",
