      q: "During surgical repair of a congenital cardiac anomaly in a 15-year-old boy with a right dominant coronary arterial system, the surgeon accidentally injured a vessel that usually supplies part of the conduction system. This results in intermittent periods of atrioventricular block and severe arrhythmia. The injured artery was most likely a direct branch of which of the following arteries?",
